{"command":"cd /testbed && python3 -c "
import csv, json, os
scores = {r['company_id']: float(r['total_score']) for r in csv.DictReader(open('data/scores.csv'))}
certs = {f[:-5]: json.load(open(f'certificates/{f}')) for f in os.listdir('certificates') if f.endswith('.json')}
expected = {c for c, s in scores.items() if s >= 60}
assert set(certs) == expected, (set(certs) ^ expected)
for c, cert in certs.items():
    assert cert['total_score'] == scores[c], (c, cert['total_score'], scores[c])
    assert cert['company_id'] == c
    for k in ('certification_date','valid_until','issued_by'): assert k in cert
print('All', len(certs), 'certificates verified: correct set, scores, and fields.')
""}
